#!/usr/bin/env python3
"""
AzaharPlus all-in-one fix.

Applies, in one go and safely to run again:
  * combo button settings (saved state fix + new dialog)
  * chat overlay live preview and presets
  * touch input bindings: gamepad/keyboard or overlay (Touch) buttons, numbered Touch buttons,
    theme tinted canvas

Usage (from Termux, in the repo):   python3 azahar_fix.py [repo_path] [--dry-run] [--force]

For every file it first checks if the change is already there (then it is skipped). Otherwise it
patches only the changed lines. If the surrounding code was edited too much for that, it
replaces the whole file and keeps a copy of yours as <file>.bak.
--force replaces all files without trying to patch.
Translations are not part of this script.
"""
import os, re, sys, json, zlib, base64

