STRINGS = json.loads(r'''{"touch_input_new_profile": "    <string name=\"touch_input_new_profile\">New</string>", "touch_input_rebind": "    <string name=\"touch_input_rebind\">Rebind</string>", "touch_input_all_bindings": "    <string name=\"touch_input_all_bindings\">All bindings (%1$d)</string>", "touch_input_touches_format": "    <string name=\"touch_input_touches_format\">Touches the screen at %1$s</string>", "touch_input_hint_drag": "    <string name=\"touch_input_hint_drag\">Drag a marker to move it \u00b7 tap empty space to add one</string>"}''')
OBSOLETE_STRINGS = ['button_touch_1', 'button_touch_2', 'button_touch_3', 'button_touch_4']
OBSOLETE_FILES = [
    'src/android/app/src/main/res/drawable/button_touch_%s%s.xml' % (n, p)
    for n in '1234' for p in ('', '_pressed')
]

def dec(s): return zlib.decompress(base64.b64decode(s)).decode('utf-8')

args = [a for a in sys.argv[1:] if not a.startswith('--')]
DRY = '--dry-run' in sys.argv
FORCE = '--force' in sys.argv
root = os.path.abspath(args[0] if args else '.')
if not os.path.isdir(os.path.join(root, 'src/android/app')):
    sys.exit('Run this inside the AzaharPlus repo (the folder that has src/android), or pass its path.')

log = {'same': 0, 'patched': 0, 'replaced': 0, 'created': 0}
def say(tag, msg): print('%-9s %s' % (tag, msg))

def write(path, text, backup=False):
    if DRY: return
    if backup and os.path.exists(path):
        with open(path, 'rb') as f, open(path + '.bak', 'wb') as g: g.write(f.read())
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'w', encoding='utf-8', newline='') as f: f.write(text)

for rel, e in sorted(ENTRIES.items()):
    path = os.path.join(root, rel)
    full = dec(e['full'])
    if not os.path.exists(path):
        write(path, full); log['created'] += 1; say('created', rel); continue
    cur = open(path, encoding='utf-8', newline='').read()
    if cur == full:
        log['same'] += 1; say('ok', rel + ' (already up to date)'); continue
    if FORCE or not e['hunks']:
        write(path, full, backup=True); log['replaced'] += 1; say('replaced', rel); continue
    text = cur; failed = False; changed = False
    for o, n in e['hunks']:
        o, n = dec(o), dec(n)
        if n in text:               # this change is already there
            continue
        if text.count(o) == 1:
            text = text.replace(o, n); changed = True; continue
        # try again without the unchanged lines around the change
        ol, nl = o.splitlines(True), n.splitlines(True)
        while ol and nl and ol[0] == nl[0]: ol.pop(0); nl.pop(0)
        while ol and nl and ol[-1] == nl[-1]: ol.pop(); nl.pop()
        oc, nc = ''.join(ol), ''.join(nl)
        if oc and text.count(oc) == 1:
            text = text.replace(oc, nc); changed = True; continue
        failed = True; break
    if failed:
        write(path, full, backup=True); log['replaced'] += 1
        say('replaced', rel + ' (could not patch, your copy saved as .bak)')
    elif changed:
        write(path, text); log['patched'] += 1; say('patched', rel)
    else:
        log['same'] += 1; say('ok', rel + ' (change already there)')

# strings.xml: add or update by name, so it never creates duplicates
sp = os.path.join(root, 'src/android/app/src/main/res/values/strings.xml')
if os.path.exists(sp):
    s = open(sp, encoding='utf-8', newline='').read()
    orig = s
    for name in OBSOLETE_STRINGS:
        s = re.sub(r'[ \t]*<string name="%s"[^>]*>.*?</string>[ \t]*\r?\n?' % re.escape(name), '', s, flags=re.S)
    added = []
    for name, xml in STRINGS.items():
        pat = re.compile(r'[ \t]*<string name="%s"[^>]*>.*?</string>' % re.escape(name), re.S)
        m = pat.search(s)
        if m:
            if m.group(0).strip() != xml.strip():
                s = s[:m.start()] + xml + s[m.end():]
        else:
            added.append(xml)
    if added:
        k = s.rindex('</resources>')
        s = s[:k] + '\n' + '\n'.join(added) + '\n' + s[k:]
    if s != orig:
        write(sp, s); say('patched', 'values/strings.xml (%d strings added or updated)' % (len(added)))
    else:
        say('ok', 'values/strings.xml (already up to date)')

ap = os.path.join(root, 'src/android/app/src/main/res/values/arrays.xml')
if os.path.exists(ap):
    a = open(ap, encoding='utf-8', newline='').read()
    b = re.sub(r'[ \t]*<item>@string/button_touch_\d</item>\r?\n', '', a)
    if a != b:
        write(ap, b); say('patched', 'values/arrays.xml (removed old fixed Touch button entries)')

for rel in OBSOLETE_FILES:
    p = os.path.join(root, rel)
    if os.path.exists(p):
        if not DRY: os.remove(p)
        say('removed', rel)

print('\nDone%s: %d up to date, %d patched, %d replaced, %d created.' % (
    ' (dry run, nothing written)' if DRY else '', log['same'], log['patched'], log['replaced'], log['created']))
print('Next: git add -A && git commit -m "..." && git push')
